export interface PanelKindIconProps {
  kind: DesktopPanelKind;
  /** 渲染宽（px）；diff 图标按 viewBox 16:17 等比增高。 */
  size?: number;
  className?: string;
}

/**
 * 五类面板类型图标（16px 网格渲染）。预览为 fill 型、其余 stroke 型，
 * 均以 currentColor 着色，父元素 color 即可控制（host-desktop.css 浅深色组）。
 */
export const PanelKindIcon: React.FC<PanelKindIconProps> = ({
  kind,
  size = 16,
  className,
}) => (
  <svg
    width={size}
    height={kind === "diff" ? Math.round((size * 17) / 16) : size}
    viewBox={KIND_VIEWBOX[kind]}
    className={className}
    aria-hidden
  >
    {KIND_PATHS[kind].map((d) =>
      kind === "preview" ? (
        <path
          key={d.slice(0, 24)}
          fillRule="evenodd"
          clipRule="evenodd"
          d={d}
          fill="currentColor"
        />
      ) : (
        <path key={d.slice(0, 24)} d={d} {...STROKE} />
      ),
    )}
  </svg>
);

export default PanelKindIcon;
